    /** Color of serie */
    color?: string;
    /** Cursor options for single serie */
    cursorOptions?: Pick<CursorOptions, 'markersSize' | 'snapToValues'>;
    /** Formatter for serie value */
    formatter?: (value: string | number | null, serie: Series) => string;
