export function formatPercent(value: number | string | null | undefined): string {
    const num = typeof value === 'string' ? Number(value) : value;
    if (num === null || num === undefined || Number.isNaN(num)) {
        return '—';
    }
    return `${percentFormatter.format(num)} %`;
}

